-- 
-- StoredProc  addFieldIfNotExists
-- 

DELIMITER $$
DROP PROCEDURE IF EXISTS `addFieldIfNotExists` $$
CREATE DEFINER=`root`@`%` PROCEDURE `addFieldIfNotExists`(
    IN table_name_IN VARCHAR(100)
    , IN field_name_IN VARCHAR(100)
    , IN field_definition_IN VARCHAR(100)
)
BEGIN
    SET @isFieldThere = isFieldExisting(table_name_IN, field_name_IN);
    IF (@isFieldThere = 0) THEN
        SET @ddl = CONCAT('ALTER TABLE ', table_name_IN);
        SET @ddl = CONCAT(@ddl, ' ', 'ADD COLUMN') ;
        SET @ddl = CONCAT(@ddl, ' ', field_name_IN);
        SET @ddl = CONCAT(@ddl, ' ', field_definition_IN);
        PREPARE stmt FROM @ddl;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;
    END IF;
END $$
DELIMITER ;


-- 
-- StoredProc  fn_BasharfiBuyuk
-- 

DELIMITER $$
DROP FUNCTION IF EXISTS `fn_BasharfiBuyuk` $$
CREATE DEFINER=`root`@`%` FUNCTION `fn_BasharfiBuyuk`(INPUT VARCHAR(255)) RETURNS varchar(255) CHARSET latin5
    DETERMINISTIC
BEGIN
    DECLARE len INT;
    DECLARE i INT;

    SET len   = CHAR_LENGTH(INPUT);
    SET INPUT = LOWER(INPUT);
    SET i = 0;

    WHILE (i < len) DO
        IF (MID(INPUT,i,1) = ' ' OR i = 0) THEN
            IF (i < len) THEN
                SET INPUT = CONCAT(
                    LEFT(INPUT,i),
                    UPPER(MID(INPUT,i + 1,1)),
                    RIGHT(INPUT,len - i - 1)
                );
            END IF;
        END IF;
        SET i = i + 1;
    END WHILE;

    RETURN INPUT;
END $$
DELIMITER ;


-- 
-- StoredProc  isFieldExisting
-- 

DELIMITER $$
DROP FUNCTION IF EXISTS `isFieldExisting` $$
CREATE DEFINER=`root`@`%` FUNCTION `isFieldExisting`(table_name_IN VARCHAR(100), field_name_IN VARCHAR(100)) RETURNS int(11)
RETURN (
    SELECT COUNT(COLUMN_NAME) 
    FROM INFORMATION_SCHEMA.columns 
    WHERE TABLE_SCHEMA = DATABASE() 
    AND TABLE_NAME = table_name_IN 
    AND COLUMN_NAME = field_name_IN
) $$
DELIMITER ;


-- 
-- StoredProc  sp_musteriemanetlerinigoster
-- 

DELIMITER $$
DROP PROCEDURE IF EXISTS `sp_musteriemanetlerinigoster` $$
CREATE DEFINER=`root`@`%` PROCEDURE `sp_musteriemanetlerinigoster`(`musid` int(11))
BEGIN

select *, 
IFNULL( (select SUM(adet) from emanetler where MUSTERIID=musid AND ISLEM='CIKIS' and ISLEMACIKLAMASI='Depodan' AND emaneturunler.RECID=emanetler.EMANETID ),0)  -
IFNULL( (select SUM(adet) from emanetler where MUSTERIID=musid AND ISLEM='GIRIS' and ISLEMACIKLAMASI='Müþteriden' AND emaneturunler.RECID=emanetler.EMANETID ),0)  AS STOK
from emaneturunler where

IFNULL( (select SUM(adet) from emanetler where MUSTERIID=musid AND ISLEM='CIKIS' and ISLEMACIKLAMASI='Depodan' AND emaneturunler.RECID=emanetler.EMANETID ),0)  -
IFNULL( (select SUM(adet) from emanetler where MUSTERIID=musid AND ISLEM='GIRIS' and ISLEMACIKLAMASI='Müþteriden' AND emaneturunler.RECID=emanetler.EMANETID ),0)>0;

END $$
DELIMITER ;


